#!/usr/bin/env node
// Build one SQL file that applies repo migrations to the shared SayThanks DB, where the
// LMS lives in the `lms` schema instead of `public` (see supabase/shared-db/README.md).
//
//   node scripts/shared-db/build-lms-bundle.mjs <from-ref> <to-ref> <out.sql>
//
// Every migration under supabase/migrations/ that exists at <to-ref> but not at <from-ref>
// is included in version order. Rewrites: `public.x` -> `lms.x`, `search_path` pinned to
// public -> `lms, public`, and `table_schema = 'public'` -> `'lms'`. `search_path = ''`
// stays as is (those bodies are fully qualified). auth.*, storage.* and extensions are
// untouched. Review the output before running it; nothing here talks to a database.
import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'

const [from, to, out] = process.argv.slice(2)
if (!from || !to || !out) {
  console.error('usage: build-lms-bundle.mjs <from-ref> <to-ref> <out.sql>')
  process.exit(1)
}

const git = (...args) => execFileSync('git', args, { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
const list = (ref) =>
  git('ls-tree', '--name-only', `${ref}`, 'supabase/migrations/')
    .split('\n')
    .filter((f) => f.endsWith('.sql'))
const before = new Set(list(from))
const files = list(to).filter((f) => !before.has(f)).sort()
if (files.length === 0) {
  console.error(`no new migrations between ${from} and ${to}`)
  process.exit(1)
}

export function toLms(sql) {
  return sql
    .replace(/(^|[^A-Za-z0-9_."])public\./g, '$1lms.')
    .replace(/search_path\s+TO\s+'public'/gi, "search_path TO 'lms', 'public'")
    .replace(/search_path\s*=\s*public\b/gi, 'search_path = lms, public')
    .replace(/table_schema\s*=\s*'public'/gi, "table_schema = 'lms'")
}

const storageLines = []
const parts = files.map((f) => {
  const name = f.replace('supabase/migrations/', '')
  const body = toLms(git('show', `${to}:${f}`))
  body.split('\n').forEach((line, i) => {
    if (/\bstorage\.(objects|buckets)\b/.test(line) && !/^\s*--/.test(line)) {
      storageLines.push(`--   ${name}:${i + 1}  ${line.trim().slice(0, 110)}`)
    }
  })
  return `-- ===========================================================================\n-- ${name}\n-- ===========================================================================\n${body.trimEnd()}\n`
})

const versions = files.map((f) => f.replace('supabase/migrations/', '').split('_')[0])
const fromSha = git('rev-parse', '--short', from).trim()
const toSha = git('rev-parse', '--short', to).trim()

const sql = `-- Shared SayThanks DB (staging): apply LMS migrations to the \`lms\` schema.
-- Generated by scripts/shared-db/build-lms-bundle.mjs from ${fromSha}..${toSha}. Do not edit by hand;
-- regenerate instead. ${files.length} migrations, in order:
${files.map((f) => `--   ${f.replace('supabase/migrations/', '')}`).join('\n')}
--
-- Run once, as postgres, in one transaction (any error rolls everything back):
--   docker exec -i saythanks-staging-db-1 psql -U postgres -d postgres -v ON_ERROR_STOP=1 -1 < THIS_FILE
--
-- Shared-schema statements to read before running (storage is used by SayThanks too).
-- They only name LMS buckets or LMS policy names, but triggers on storage.objects fire
-- for every bucket:
${storageLines.join('\n')}

\\set ON_ERROR_STOP on
SET LOCAL search_path = lms, public, extensions;

-- Preflight: refuse to run against a schema that is not the pre-sync baseline.
-- The ledger query is dynamic SQL: a static reference to a table that does not exist
-- yet fails when PL/pgSQL plans it, even behind a to_regclass() check.
DO $preflight$
DECLARE
  already boolean := false;
BEGIN
  IF to_regclass('lms.tenants') IS NULL THEN
    RAISE EXCEPTION 'lms.tenants not found: wrong database or schema';
  END IF;
  IF to_regclass('lms.lms_migration_log') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM lms.lms_migration_log WHERE version = ANY ($1))'
      INTO already
      USING ARRAY[${versions.map((v) => `'${v}'`).join(', ')}]::text[];
    IF already THEN
      RAISE EXCEPTION 'some of these migrations are already recorded in lms.lms_migration_log';
    END IF;
  END IF;
END
$preflight$;

-- Ledger of what has been applied to the shared schema (the shared DB has no
-- supabase_migrations history for \`lms\`). Service-only.
CREATE TABLE IF NOT EXISTS lms.lms_migration_log (
  version    text PRIMARY KEY,
  name       text NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now()
);
REVOKE ALL ON lms.lms_migration_log FROM anon, authenticated;

${parts.join('\n')}
-- Record what this bundle applied.
INSERT INTO lms.lms_migration_log (version, name) VALUES
${files.map((f) => { const n = f.replace('supabase/migrations/', ''); return `  ('${n.split('_')[0]}', '${n.replace(/'/g, "''")}')` }).join(',\n')};

-- Functions created with a public search_path elsewhere still need lms first (same as
-- supabase/shared-db/lms-schema-search-path.sql).
DO $fix$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'lms' AND p.proconfig @> ARRAY['search_path=public']
  LOOP
    EXECUTE 'ALTER FUNCTION ' || r.sig || ' SET search_path = lms, public';
  END LOOP;
END
$fix$;

NOTIFY pgrst, 'reload schema';
`
writeFileSync(out, sql)
console.log(`wrote ${out}: ${files.length} migrations, ${storageLines.length} storage lines flagged`)
